package com.sza.fastmediasorter.domain.model

import com.google.gson.JsonElement
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * Replay of contract DEVICE-EXCHANGE 5.5's conformance artifact `vectors/connection-string-v1.json`, generated by
 * FMS_W. The file under test resources is the catalog artifact byte for byte and is never edited here: a case that
 * fails is a disagreement between two readers, settled in the catalog.
 */
class ExchangeConnectionStringVectorsTest {

    private val cases: List<JsonObject> = checkNotNull(
        javaClass.classLoader?.getResourceAsStream("device-exchange/connection-string-v1.json"),
    ) { "connection-string-v1.json test resource missing" }
        .use { JsonParser.parseString(it.readBytes().toString(Charsets.UTF_8)).asJsonObject }
        .getAsJsonArray("cases")
        .map(JsonElement::getAsJsonObject)

    private fun JsonObject.text(key: String): String? = get(key)?.takeUnless { it.isJsonNull }?.asString

    private fun JsonObject.inputBytes(): ByteArray = text("inputHex")
        ?.chunked(2) { it.toString().toInt(HEX_RADIX).toByte() }
        ?.toByteArray()
        ?: text("input").orEmpty().toByteArray(Charsets.UTF_8)

    private fun decode(case: JsonObject): ExchangeConnectionStringResult = when (case.text("kind")) {
        "file" -> ExchangeConnectionStringCodec.decodeFile(case.inputBytes())
        else -> ExchangeConnectionStringCodec.decode(case.inputBytes().toString(Charsets.UTF_8))
    }

    @Test
    fun `the artifact covers every verdict`() {
        val verdicts = cases.groupingBy { it.text("verdict") }.eachCount()
        assertTrue(verdicts.toString(), (verdicts["valid"] ?: 0) >= MIN_VALID)
        assertTrue(verdicts.toString(), (verdicts["tolerated"] ?: 0) >= MIN_TOLERATED)
        assertTrue(verdicts.toString(), (verdicts["refused"] ?: 0) >= MIN_REFUSED)
    }

    @Test
    fun `every valid and tolerated case reads its fields and re-writes its canonical text`() {
        cases.filter { it.text("verdict") != "refused" }.forEach { case ->
            val name = checkNotNull(case.text("name"))
            val result = decode(case)
            if (result !is ExchangeConnectionStringResult.Read) fail("$name: expected a read, got $result")
            val value = (result as ExchangeConnectionStringResult.Read).value
            assertEquals(name, case.text("canonical"), value.encode())
            val fields = case.getAsJsonObject("fields")
            assertEquals(name, fields.text("x"), value.endpoint.toString())
            assertEquals(name, fields.text("host"), value.endpoint.host)
            assertEquals(name, fields.get("port").asInt, value.endpoint.port)
            assertEquals(name, fields.text("fp"), value.fingerprint)
            assertEquals(name, fields.text("n"), value.name)
            assertEquals(name, fields.text("u"), value.loginHint)
        }
    }

    @Test
    fun `every refused case is refused whole with its reason`() {
        cases.filter { it.text("verdict") == "refused" }.forEach { case ->
            val name = checkNotNull(case.text("name"))
            when (val result = decode(case)) {
                is ExchangeConnectionStringResult.NewerMajor -> assertEquals(name, "newer-major", case.text("reason"))
                is ExchangeConnectionStringResult.Refused -> {
                    assertEquals(name, case.text("reason"), result.reason.code)
                    assertEquals(name, case.text("looks"), result.looks?.code)
                }
                is ExchangeConnectionStringResult.Read -> fail("$name: expected a refusal, read ${result.value}")
            }
        }
    }

    private companion object {
        const val HEX_RADIX = 16
        const val MIN_VALID = 16
        const val MIN_TOLERATED = 14
        const val MIN_REFUSED = 60
    }
}
